//
//  TranslationDirection.swift
//  SwiftMandarin
//
//  Translation direction enum for English ↔ Chinese
//

import Foundation
import SwiftUI

enum TranslationDirection: String, CaseIterable, Identifiable, Codable {
    case englishToChinese
    case chineseToEnglish

    var id: String { rawValue }

    var label: String {
        switch self {
        case .englishToChinese: return "EN → 中"
        case .chineseToEnglish: return "中 → EN"
        }
    }

    var sourceLabel: String {
        switch self {
        case .englishToChinese: return "English"
        case .chineseToEnglish: return "中文"
        }
    }

    var targetLabel: String {
        switch self {
        case .englishToChinese: return "中文"
        case .chineseToEnglish: return "English"
        }
    }

    var placeholder: String {
        switch self {
        case .englishToChinese: return "Enter English text..."
        case .chineseToEnglish: return "输入中文..."
        }
    }

    var sourceLanguage: Locale.Language {
        switch self {
        case .englishToChinese: return Locale.Language(identifier: "en")
        case .chineseToEnglish: return Locale.Language(identifier: "zh-Hans")
        }
    }

    var targetLanguage: Locale.Language {
        switch self {
        case .englishToChinese: return Locale.Language(identifier: "zh-Hans")
        case .chineseToEnglish: return Locale.Language(identifier: "en")
        }
    }

    var sourceSpeechCode: String {
        switch self {
        case .englishToChinese: return "en-US"
        case .chineseToEnglish: return "zh-CN"
        }
    }

    var targetSpeechCode: String {
        switch self {
        case .englishToChinese: return "zh-CN"
        case .chineseToEnglish: return "en-US"
        }
    }

    var opposite: TranslationDirection {
        self == .englishToChinese ? .chineseToEnglish : .englishToChinese
    }

    var sourceLanguageName: String {
        switch self {
        case .englishToChinese: return "English"
        case .chineseToEnglish: return "Chinese"
        }
    }

    var targetLanguageName: String {
        switch self {
        case .englishToChinese: return "Chinese"
        case .chineseToEnglish: return "English"
        }
    }

    func toggled() -> TranslationDirection {
        opposite
    }
}

//
//  OllamaService.swift
//  SwiftMandarin
//
//  Service for interacting with local Ollama models as an alternative to Apple Intelligence.
//  Provides model discovery, chat completion, and structured output generation.
//

import Foundation
import SwiftUI
import Ollama

// MARK: - Ollama Model Info

/// Represents an available Ollama model with its metadata
struct OllamaModelInfo: Identifiable, Hashable, Codable {
    var id: String { name }
    let name: String
    let size: Int64
    let parameterSize: String
    let family: String
    let supportsThinking: Bool
    let supportsTools: Bool

    /// Human-readable size string
    var sizeString: String {
        let formatter = ByteCountFormatter()
        formatter.countStyle = .file
        return formatter.string(fromByteCount: size)
    }
}

// MARK: - Ollama Service

/// Service that provides access to local Ollama models for AI-powered features
@Observable
@MainActor
final class OllamaService {

    static let shared = OllamaService()

    // MARK: - Properties

    /// The Ollama client instance
    private var client: Ollama.Client

    /// Available models discovered from Ollama
    private(set) var availableModels: [OllamaModelInfo] = []

    /// Whether Ollama server is reachable
    private(set) var isConnected: Bool = false

    /// Last connection error if any
    private(set) var connectionError: String?

    /// Whether we're currently loading models
    private(set) var isLoadingModels: Bool = false

    /// The Ollama server host URL
    var hostURL: URL {
        get { client.host }
        set { 
            client = Ollama.Client(host: newValue)
            // Re-check connection when host changes
            Task { await checkConnection() }
        }
    }

    // MARK: - Configuration

    /// Default options for gpt-oss 20b model with extended context and reasoning
    static let defaultOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),           // 128k context window
        "temperature": .double(0.7),        // Balanced creativity
        "top_p": .double(0.9),              // Nucleus sampling
        "repeat_penalty": .double(1.1),     // Reduce repetition
        "num_predict": .int(-1),            // No limit on tokens
    ]

    /// Options optimized for reasoning tasks
    static let reasoningOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),            // 128k context window
        "temperature": .double(0.3),         // More deterministic for reasoning
        "top_p": .double(0.95),
        "repeat_penalty": .double(1.05),
        "num_predict": .int(-1),
    ]

    // MARK: - Initialization

    private init() {
        // Initialize with default localhost
        self.client = Ollama.Client.default
    }

    // MARK: - Connection Management

    /// Check if Ollama server is reachable
    func checkConnection() async {
        do {
            _ = try await client.version()
            isConnected = true
            connectionError = nil
        } catch {
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    /// Refresh the list of available models from Ollama
    func refreshModels() async {
        isLoadingModels = true
        defer { isLoadingModels = false }

        do {
            let response = try await client.listModels()

            // Get detailed info for each model to check capabilities
            var models: [OllamaModelInfo] = []
            for model in response.models {
                // Try to get capabilities for each model
                var supportsThinking = false
                var supportsTools = false

                do {
                    let details = try await client.showModel(Ollama.Model.ID(rawValue: model.name)!)
                    supportsThinking = details.capabilities.contains(.thinking)
                    supportsTools = details.capabilities.contains(.tools)
                } catch {
                    // Ignore errors fetching details, use defaults
                }

                let info = OllamaModelInfo(
                    name: model.name,
                    size: model.size,
                    parameterSize: model.details.parameterSize,
                    family: model.details.family,
                    supportsThinking: supportsThinking,
                    supportsTools: supportsTools
                )
                models.append(info)
            }

            availableModels = models.sorted { $0.name < $1.name }
            isConnected = true
            connectionError = nil
        } catch {
            availableModels = []
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    // MARK: - Chat Completion

    /// Generate a chat completion with the specified model
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions for the model
    ///   - userPrompt: The user's message
    ///   - enableThinking: Whether to enable thinking/reasoning mode
    ///   - options: Additional model options
    /// - Returns: The model's response content
    func chat(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) async throws -> (content: String, thinking: String?) {
        let modelID = Ollama.Model.ID(rawValue: model)!

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return (content: response.message.content, thinking: response.message.thinking)
    }

    /// Generate a streaming chat completion
    func chatStream(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) throws -> AsyncThrowingStream<Ollama.Client.ChatResponse, Error> {
        let modelID = Ollama.Model.ID(rawValue: model)!

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        return try client.chatStream(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )
    }

    // MARK: - Structured Output Generation

    /// Generate a structured JSON response matching a schema
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions
    ///   - userPrompt: User message
    ///   - schema: JSON schema for the expected output
    ///   - enableThinking: Whether to enable thinking mode
    /// - Returns: The JSON string response
    func generateStructured(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        schema: Ollama.Value,
        enableThinking: Bool = true
    ) async throws -> String {
        let modelID = Ollama.Model.ID(rawValue: model)!

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: Self.reasoningOptions,
            format: schema,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return response.message.content
    }

    /// Generate structured output and decode it to a Codable type
    func generateAndDecode<T: Codable>(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        type: T.Type,
        enableThinking: Bool = true
    ) async throws -> T {
        // Build JSON schema from type (simplified approach)
        let jsonString = try await generateStructured(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            schema: "json",
            enableThinking: enableThinking
        )

        guard let data = jsonString.data(using: .utf8) else {
            throw OllamaServiceError.invalidResponse("Response is not valid UTF-8")
        }

        do {
            return try JSONDecoder().decode(T.self, from: data)
        } catch {
            throw OllamaServiceError.decodingFailed("Failed to decode response: \(error.localizedDescription)")
        }
    }

    // MARK: - Translation

    /// Translate text using Ollama
    /// - Parameters:
    ///   - text: The text to translate
    ///   - sourceIsChinese: Whether the source is Chinese (true) or English (false)
    ///   - model: The model to use
    /// - Returns: The translated text
    func translate(
        _ text: String,
        sourceIsChinese: Bool,
        model: String
    ) async throws -> String {
        let systemPrompt = """
        You are an expert translator specializing in English and Mandarin Chinese (Simplified).

        Your translations should be:
        1. ACCURATE: Preserve the exact meaning and intent of the source text
        2. NATURAL: Use idiomatic expressions appropriate for the target language
        3. CONTEXTUAL: Consider the context and register (formal/informal)
        4. CULTURAL: Adapt cultural references when necessary for clarity

        For English to Chinese translations:
        - Use Simplified Chinese characters (简体中文)
        - Choose vocabulary appropriate for modern standard Mandarin (普通话)
        - Maintain the tone and style of the original

        For Chinese to English translations:
        - Use natural, fluent English
        - Preserve nuances and connotations where possible
        - Clarify ambiguous cultural references if needed

        Respond with ONLY the translation, no explanations or additional text.
        """

        let direction = sourceIsChinese ? "Chinese to English" : "English to Chinese"
        let userPrompt = """
        Translate the following text from \(direction):

        \(text)
        """

        let (content, _) = try await chat(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            enableThinking: false, // Translation doesn't need reasoning
            options: Self.defaultOptions
        )

        return content.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

// MARK: - Errors

enum OllamaServiceError: LocalizedError {
    case notConnected
    case modelNotFound(String)
    case invalidResponse(String)
    case decodingFailed(String)
    case generationFailed(String)

    var errorDescription: String? {
        switch self {
        case .notConnected:
            return "Ollama server is not connected. Please ensure Ollama is running."
        case .modelNotFound(let name):
            return "Model '\(name)' not found. Please pull the model first."
        case .invalidResponse(let detail):
            return "Invalid response from Ollama: \(detail)"
        case .decodingFailed(let detail):
            return "Failed to decode response: \(detail)"
        case .generationFailed(let detail):
            return "Generation failed: \(detail)"
        }
    }
}

//
//  AIWordExplanationView.swift
//  SwiftMandarin
//
//  A reusable view component that displays AI-generated word explanations
//  using either Apple Intelligence or Ollama based on user settings
//

import SwiftUI

/// A view that displays a detailed AI-generated explanation for a Mandarin word
struct AIWordExplanationView: View {
    let word: String
    let pinyin: String
    let context: String?

    @State private var explanation: WordExplanationResult?
    @State private var isLoading: Bool = false
    @State private var errorMessage: String?
    @State private var expandedSections: Set<String> = ["definition", "examples"]

    private let aiService = AIWordExplanationService.shared
    private let aiSettings = AIModelSettings.shared

    /// Check if any AI provider is available
    private var isAnyProviderAvailable: Bool {
        aiSettings.isAppleIntelligenceAvailable || OllamaService.shared.isConnected
    }

    /// Get the current provider name for display
    private var currentProviderName: String {
        aiSettings.effectiveProvider.displayName
    }

    /// Get the icon for the current provider
    private var currentProviderIcon: String {
        aiSettings.effectiveProvider.iconName
    }

    var body: some View {
        Group {
            if !isAnyProviderAvailable {
                unavailableView
            } else if isLoading {
                loadingView
            } else if let error = errorMessage {
                errorView(error)
            } else if let explanation = explanation {
                explanationContent(explanation)
            } else {
                generateButton
            }
        }
    }

    // MARK: - Unavailable State

    private var unavailableView: some View {
        VStack(spacing: 12) {
            Image(systemName: "cpu")
                .font(.system(size: 32))
                .foregroundStyle(.secondary)

            Text("AI Not Available")
                .font(.headline)

            Text("Enable Apple Intelligence or connect to Ollama in Settings to use AI features.")
                .font(.caption)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)
        }
        .padding()
        .frame(maxWidth: .infinity)
    }

    // MARK: - Loading State

    private var loadingView: some View {
        VStack(spacing: 16) {
            ProgressView()
                .controlSize(.large)

            Text("Generating explanation...")
                .font(.subheadline)
                .foregroundStyle(.secondary)

            Text("Using \(currentProviderName)")
                .font(.caption2)
                .foregroundStyle(.tertiary)
        }
        .padding(.vertical, 32)
        .frame(maxWidth: .infinity)
    }

    // MARK: - Error State

    private func errorView(_ message: String) -> some View {
        VStack(spacing: 12) {
            Image(systemName: "exclamationmark.triangle")
                .font(.system(size: 28))
                .foregroundStyle(.orange)

            Text("Could not generate explanation")
                .font(.headline)

            Text(message)
                .font(.caption)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)

            Button {
                Task { await generateExplanation() }
            } label: {
                Label("Try Again", systemImage: "arrow.clockwise")
            }
            .buttonStyle(.bordered)
        }
        .padding()
        .frame(maxWidth: .infinity)
    }

    // MARK: - Generate Button

    private var generateButton: some View {
        VStack(spacing: 16) {
            Spacer()
                .frame(height: 40)

            Image(systemName: currentProviderIcon)
                .font(.system(size: 36))
                .foregroundStyle(.blue)

            Text("Get a detailed explanation of this word including nuances, grammar usage, examples, and more.")
                .font(.caption)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)

            Button {
                Task { await generateExplanation() }
            } label: {
                Label("Explain with \(currentProviderName)", systemImage: "sparkles")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.large)

            Spacer()
        }
        .padding()
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
    }

    // MARK: - Explanation Content

    @ViewBuilder
    private func explanationContent(_ explanation: WordExplanationResult) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            // AI badge header
            HStack {
                Image(systemName: currentProviderIcon)
                    .foregroundStyle(.blue)
                Text(currentProviderName)
                    .font(.caption)
                    .fontWeight(.medium)
                    .foregroundStyle(.blue)
                Spacer()
                Button {
                    Task { await generateExplanation() }
                } label: {
                    Image(systemName: "arrow.clockwise")
                        .font(.caption)
                }
                .buttonStyle(.plain)
                .foregroundStyle(.secondary)
            }
            .padding(.horizontal)
            .padding(.vertical, 8)
            .background(.blue.opacity(0.1))

            ScrollView {
                VStack(alignment: .leading, spacing: 16) {
                    // Definition Section
                    collapsibleSection(
                        title: "Definition",
                        icon: "text.book.closed",
                        id: "definition"
                    ) {
                        VStack(alignment: .leading, spacing: 8) {
                            if !explanation.partOfSpeech.isEmpty {
                                Text(explanation.partOfSpeech)
                                    .font(.caption)
                                    .fontWeight(.semibold)
                                    .foregroundStyle(.white)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 3)
                                    .background(Capsule().fill(.blue))
                            }

                            Text(explanation.definition)
                                .font(.body)
                        }
                    }

                    // Nuances Section
                    if !explanation.nuances.isEmpty {
                        collapsibleSection(
                            title: "Nuances & Context",
                            icon: "lightbulb",
                            id: "nuances"
                        ) {
                            Text(explanation.nuances)
                                .font(.callout)
                        }
                    }

                    // Grammar Usage Section
                    if !explanation.grammarUsage.isEmpty {
                        collapsibleSection(
                            title: "Grammar Usage",
                            icon: "text.alignleft",
                            id: "grammar"
                        ) {
                            Text(explanation.grammarUsage)
                                .font(.callout)
                        }
                    }

                    // Usage Contexts Section
                    if !explanation.usageContexts.isEmpty {
                        collapsibleSection(
                            title: "When to Use",
                            icon: "bubble.left.and.bubble.right",
                            id: "contexts"
                        ) {
                            VStack(alignment: .leading, spacing: 6) {
                                ForEach(explanation.usageContexts, id: \.self) { context in
                                    HStack(alignment: .top, spacing: 8) {
                                        Image(systemName: "checkmark.circle.fill")
                                            .foregroundStyle(.green)
                                            .font(.caption)
                                        Text(context)
                                            .font(.callout)
                                    }
                                }
                            }
                        }
                    }

                    // Example Sentences Section
                    if !explanation.exampleSentences.isEmpty {
                        collapsibleSection(
                            title: "Examples",
                            icon: "text.quote",
                            id: "examples"
                        ) {
                            VStack(alignment: .leading, spacing: 12) {
                                ForEach(explanation.exampleSentences) { sentence in
                                    exampleSentenceRow(sentence)
                                }
                            }
                        }
                    }

                    // Synonyms Section
                    if !explanation.synonyms.isEmpty {
                        collapsibleSection(
                            title: "Synonyms",
                            icon: "equal.circle",
                            id: "synonyms"
                        ) {
                            VStack(alignment: .leading, spacing: 10) {
                                ForEach(explanation.synonyms) { synonym in
                                    relatedWordRow(synonym, tint: .blue)
                                }
                            }
                        }
                    }

                    // Antonyms Section
                    if !explanation.antonyms.isEmpty {
                        collapsibleSection(
                            title: "Antonyms",
                            icon: "arrow.left.arrow.right",
                            id: "antonyms"
                        ) {
                            VStack(alignment: .leading, spacing: 10) {
                                ForEach(explanation.antonyms) { antonym in
                                    relatedWordRow(antonym, tint: .orange)
                                }
                            }
                        }
                    }

                    // Common Collocations Section
                    if !explanation.commonCollocations.isEmpty {
                        collapsibleSection(
                            title: "Common Phrases",
                            icon: "text.badge.plus",
                            id: "collocations"
                        ) {
                            VStack(alignment: .leading, spacing: 8) {
                                ForEach(explanation.commonCollocations) { collocation in
                                    collocationRow(collocation)
                                }
                            }
                        }
                    }

                    // Learning Tip Section
                    if !explanation.learningTip.isEmpty {
                        collapsibleSection(
                            title: "Learning Tip",
                            icon: "graduationcap",
                            id: "tip"
                        ) {
                            HStack(alignment: .top, spacing: 10) {
                                Image(systemName: "lightbulb.fill")
                                    .foregroundStyle(.yellow)
                                Text(explanation.learningTip)
                                    .font(.callout)
                                    .italic()
                            }
                            .padding()
                            .background(
                                RoundedRectangle(cornerRadius: 8)
                                    .fill(.yellow.opacity(0.1))
                            )
                        }
                    }
                }
                .padding()
            }
        }
    }

    // MARK: - Section Components

    @ViewBuilder
    private func collapsibleSection<Content: View>(
        title: String,
        icon: String,
        id: String,
        @ViewBuilder content: () -> Content
    ) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Button {
                withAnimation(.easeInOut(duration: 0.2)) {
                    if expandedSections.contains(id) {
                        expandedSections.remove(id)
                    } else {
                        expandedSections.insert(id)
                    }
                }
            } label: {
                HStack {
                    Image(systemName: icon)
                        .foregroundStyle(.secondary)
                        .frame(width: 20)

                    Text(title)
                        .font(.subheadline)
                        .fontWeight(.semibold)
                        .foregroundStyle(.primary)

                    Spacer()

                    Image(systemName: expandedSections.contains(id) ? "chevron.up" : "chevron.down")
                        .font(.caption)
                        .foregroundStyle(.tertiary)
                }
            }
            .buttonStyle(.plain)

            if expandedSections.contains(id) {
                content()
                    .padding(.leading, 28)
            }
        }
        .padding(.vertical, 4)
    }

    private func exampleSentenceRow(_ sentence: ExampleSentenceResult) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(sentence.chinese)
                .font(.body)
                .fontWeight(.medium)

            Text(PinyinConverter.coloredPinyin(fromPinyin: sentence.pinyin))
                .font(.caption)

            Text(sentence.english)
                .font(.caption)
                .foregroundStyle(.secondary)
        }
        .padding(.vertical, 6)
        .padding(.horizontal, 10)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 8)
                .fill(.quaternary.opacity(0.5))
        )
    }

    private func relatedWordRow(_ word: RelatedWordResult, tint: Color) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            HStack(spacing: 8) {
                Text(word.chinese)
                    .font(.body)
                    .fontWeight(.medium)

                Text(word.pinyin)
                    .font(.caption)
                    .foregroundStyle(.secondary)

                Spacer()

                Text(word.meaning)
                    .font(.caption)
                    .foregroundStyle(tint)
            }

            if !word.difference.isEmpty {
                Text(word.difference)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .padding(.vertical, 4)
    }

    private func collocationRow(_ collocation: CollocationResult) -> some View {
        HStack(spacing: 12) {
            VStack(alignment: .leading, spacing: 2) {
                Text(collocation.chinese)
                    .font(.callout)
                    .fontWeight(.medium)

                Text(collocation.pinyin)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }

            Spacer()

            Text(collocation.english)
                .font(.caption)
                .foregroundStyle(.secondary)
        }
        .padding(.vertical, 4)
    }

    // MARK: - Actions

    private func generateExplanation() async {
        isLoading = true
        errorMessage = nil

        do {
            // Use the unified provider method that routes to Apple Intelligence or Ollama
            explanation = try await aiService.generateExplanationWithProvider(
                for: word,
                pinyin: pinyin,
                context: context
            )
        } catch {
            errorMessage = error.localizedDescription
        }

        isLoading = false
    }
}

// MARK: - Compact AI Button for List Rows

/// A small button that can be added to vocabulary rows to trigger AI explanation
struct AIExplainButton: View {
    let word: String
    let pinyin: String
    let onTap: () -> Void

    @State private var isAvailable: Bool = true

    private var providerIcon: String {
        AIModelSettings.shared.effectiveProvider.iconName
    }

    private var providerName: String {
        AIModelSettings.shared.effectiveProvider.displayName
    }

    var body: some View {
        Button(action: onTap) {
            Image(systemName: providerIcon)
                .font(.system(size: 14))
                .foregroundStyle(isAvailable ? .blue : .secondary)
        }
        .buttonStyle(.plain)
        .disabled(!isAvailable)
        .help(isAvailable ? "Explain with \(providerName)" : "AI not available")
        .onAppear {
            isAvailable = AIModelSettings.shared.isAppleIntelligenceAvailable || OllamaService.shared.isConnected
        }
    }
}

