import Foundation
import AppIntents

struct SpeakTranslationIntent: AppIntent {
    static var title: LocalizedStringResource = "Speak Translation"
    static var description = IntentDescription("Translate and speak text in the target language, or speak the original text.")

    @Parameter(title: "Text", inputOptions: .init(capitalizationType: .sentences))
    var text: String

    @Parameter(title: "Direction", default: .auto)
    var direction: ShortcutTranslationDirection

    @Parameter(title: "Use Apple Intelligence", default: false)
    var useAI: Bool

    @Parameter(title: "Speak", default: .translated)
    var speakTarget: ShortcutSpeakTarget

    static var parameterSummary: some ParameterSummary {
        Summary("Speak \(\.$text)") {
            \.$direction
            \.$useAI
            \.$speakTarget
        }
    }

    @MainActor
    func perform() async throws -> some IntentResult {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw TranslationIntentError.emptyText
        }

        let resolvedDirection = ShortcutHelpers.resolveDirection(for: trimmed, preferred: direction)

        switch speakTarget {
        case .source:
            if resolvedDirection == .chineseToEnglish {
                SpeechService.speakChinese(trimmed)
            } else {
                SpeechService.speakEnglish(trimmed)
            }
            return .result()
        case .translated:
            let result = try await ShortcutHelpers.translate(trimmed, direction: resolvedDirection, useAI: useAI)
            if resolvedDirection == .chineseToEnglish {
                SpeechService.speakEnglish(result.translation)
            } else {
                SpeechService.speakChinese(result.translation)
            }
            return .result()
        }
    }
}

//
//  PhotoTextRecognitionService.swift
//  SwiftMandarin
//
//  Photo OCR service using Apple Vision framework
//  Recognizes text in images for translation
//

import Foundation
import Vision
import SwiftUI

#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

/// Result of text recognition from an image
struct RecognizedTextBlock: Identifiable, Sendable {
    let id = UUID()
    let text: String
    let confidence: Float
    let boundingBox: CGRect
}

/// Combined recognition result
struct TextRecognitionResult: Sendable {
    let blocks: [RecognizedTextBlock]
    let fullText: String
    let cleanedText: String  // Text with line breaks cleaned up for sentence processing
    let language: String?

    var isEmpty: Bool { blocks.isEmpty }

    init(blocks: [RecognizedTextBlock]) {
        self.blocks = blocks
        self.fullText = blocks.map { $0.text }.joined(separator: "\n")
        self.cleanedText = TextRecognitionResult.cleanTextForSentences(blocks.map { $0.text }.joined(separator: " "))
        self.language = nil
    }

    /// Clean OCR text to properly join sentences split by line breaks
    /// This is important for textbook scanning where sentences may span multiple lines
    private static func cleanTextForSentences(_ text: String) -> String {
        var result = text

        // Replace multiple whitespace/newlines with single space
        result = result.replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)

        // Fix common OCR issues where sentences are split by line breaks
        // Pattern: lowercase letter followed by newline/space followed by lowercase letter (likely mid-sentence)
        // Keep line breaks after sentence-ending punctuation

        // First, normalize all whitespace to single spaces
        result = result.components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")

        // Fix hyphenated words split across lines (e.g., "com- municate" -> "communicate")
        result = result.replacingOccurrences(of: "- ", with: "")

        // Ensure proper spacing after punctuation
        result = result.replacingOccurrences(of: "\\.([A-Z])", with: ". $1", options: .regularExpression)
        result = result.replacingOccurrences(of: "\\?([A-Z])", with: "? $1", options: .regularExpression)
        result = result.replacingOccurrences(of: "!([A-Z])", with: "! $1", options: .regularExpression)

        // Clean up multiple spaces
        result = result.replacingOccurrences(of: "  +", with: " ", options: .regularExpression)

        return result.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

/// Errors that can occur during text recognition
enum RecognitionError: LocalizedError {
    case invalidImage
    case recognitionFailed(String)
    case noTextFound
    case unsupportedPlatform

    var errorDescription: String? {
        switch self {
        case .invalidImage:
            return "无法处理图片"
        case .recognitionFailed(let message):
            return "识别失败: \(message)"
        case .noTextFound:
            return "未找到文字"
        case .unsupportedPlatform:
            return "当前平台不支持此功能"
        }
    }
}

/// Service for recognizing text in images using Vision framework
@Observable
@MainActor
final class PhotoTextRecognitionService {

    static let shared = PhotoTextRecognitionService()

    /// Current recognition state
    var isProcessing: Bool = false
    var lastError: String?
    var lastResult: TextRecognitionResult?

    private init() {}

    // MARK: - Public Methods

    /// Recognize text in a CGImage
    func recognizeText(in cgImage: CGImage) async throws -> TextRecognitionResult {
        isProcessing = true
        lastError = nil

        defer { isProcessing = false }

        do {
            let blocks = try await performRecognition(cgImage: cgImage)

            if blocks.isEmpty {
                throw RecognitionError.noTextFound
            }

            let result = TextRecognitionResult(blocks: blocks)
            lastResult = result
            return result
        } catch {
            lastError = error.localizedDescription
            throw error
        }
    }

    #if canImport(UIKit)
    /// Recognize text in a UIImage
    func recognizeText(in image: UIImage) async throws -> TextRecognitionResult {
        guard let cgImage = image.cgImage else {
            throw RecognitionError.invalidImage
        }
        return try await recognizeText(in: cgImage)
    }
    #endif

    #if canImport(AppKit)
    /// Recognize text in an NSImage
    func recognizeText(in image: NSImage) async throws -> TextRecognitionResult {
        guard let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            throw RecognitionError.invalidImage
        }
        return try await recognizeText(in: cgImage)
    }
    #endif

    /// Recognize text from image data
    func recognizeText(from data: Data) async throws -> TextRecognitionResult {
        #if canImport(UIKit)
        guard let image = UIImage(data: data), let cgImage = image.cgImage else {
            throw RecognitionError.invalidImage
        }
        #elseif canImport(AppKit)
        guard let image = NSImage(data: data),
              let cgImage = image.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            throw RecognitionError.invalidImage
        }
        #endif

        return try await recognizeText(in: cgImage)
    }

    // MARK: - Private Methods

    private func performRecognition(cgImage: CGImage) async throws -> [RecognizedTextBlock] {
        try await withCheckedThrowingContinuation { continuation in
            let request = VNRecognizeTextRequest { request, error in
                if let error = error {
                    continuation.resume(throwing: RecognitionError.recognitionFailed(error.localizedDescription))
                    return
                }

                guard let observations = request.results as? [VNRecognizedTextObservation] else {
                    continuation.resume(returning: [])
                    return
                }

                let blocks = observations.compactMap { observation -> RecognizedTextBlock? in
                    // Get the top candidate for each observation
                    guard let candidate = observation.topCandidates(1).first else { return nil }

                    return RecognizedTextBlock(
                        text: candidate.string,
                        confidence: candidate.confidence,
                        boundingBox: observation.boundingBox
                    )
                }

                continuation.resume(returning: blocks)
            }

            // Configure for accurate recognition
            request.recognitionLevel = .accurate

            // Prioritize English for textbook scanning
            request.recognitionLanguages = ["en-US", "en-GB", "zh-Hans", "zh-Hant"]

            // Enable language correction for better accuracy
            request.usesLanguageCorrection = true

            // Use revision 3 for best accuracy (iOS 16+)
            if #available(iOS 16.0, macOS 13.0, *) {
                request.revision = VNRecognizeTextRequestRevision3
            }

            let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])

            do {
                try handler.perform([request])
            } catch {
                continuation.resume(throwing: RecognitionError.recognitionFailed(error.localizedDescription))
            }
        }
    }

    /// Clear the last result and error
    func reset() {
        lastResult = nil
        lastError = nil
    }
}

//
//  TranslateScreenshotsIntent.swift
//  SwiftMandarin
//
//  App Intent for translating multiple screenshots
//  Stitches images, performs OCR, and displays translated overlay
//

import Foundation
import AppIntents
import SwiftUI

#if canImport(UIKit)
import UIKit
#endif

/// App Intent for translating screenshots via Shortcuts
struct TranslateScreenshotsIntent: AppIntent {
    static var title: LocalizedStringResource = "Translate Screenshots"

    static var description = IntentDescription(
        "Stitch multiple screenshots together, extract text, and translate to English or Chinese. Perfect for translating long web pages or documents captured as multiple screenshots."
    )

    /// Must open the app to display the overlay
    static var openAppWhenRun: Bool = true

    // MARK: - Parameters

    @Parameter(
        title: "Screenshots",
        description: "One or more screenshots to translate. If multiple images are provided, they will be stitched together with overlapping regions automatically removed.",
        supportedTypeIdentifiers: ["public.image"]
    )
    var images: [IntentFile]

    @Parameter(
        title: "Target Language",
        description: "The language to translate the text into.",
        default: .english
    )
    var targetLanguage: ShortcutTargetLanguage

    // MARK: - Parameter Summary

    static var parameterSummary: some ParameterSummary {
        Summary("Translate \\(\\.$images) to \\(\\.$targetLanguage)")
    }

    // MARK: - Perform

    @MainActor
    func perform() async throws -> some IntentResult {
        // Validate we have images
        guard !images.isEmpty else {
            throw TranslationIntentError.emptyText
        }

        #if os(iOS)
        // Load UIImages from IntentFile data
        var uiImages: [UIImage] = []

        for file in images {
            let data = file.data
            if let image = UIImage(data: data) {
                uiImages.append(image)
            }
        }

        guard !uiImages.isEmpty else {
            throw TranslationIntentError.invalidImages
        }

        // Set up the shared store
        let store = ScreenshotTranslationStore.shared
        store.pendingImages = uiImages
        store.targetLanguage = targetLanguage.toScreenshotTargetLanguage

        // Trigger the app to show the overlay
        AppRouteStore.shared.trigger(.translateScreenshots, preferredTab: .photo)

        // Start processing in background
        Task {
            await store.processScreenshots()
        }

        return .result(
            dialog: IntentDialog("Opening translation view for \(uiImages.count) screenshot(s)...")
        )
        #else
        // macOS - load NSImages instead
        var nsImages: [NSImage] = []

        for file in images {
            let data = file.data
            if let image = NSImage(data: data) {
                nsImages.append(image)
            }
        }

        guard !nsImages.isEmpty else {
            throw TranslationIntentError.invalidImages
        }

        // Set up the shared store
        let store = ScreenshotTranslationStore.shared
        store.pendingImages = nsImages
        store.targetLanguage = targetLanguage.toScreenshotTargetLanguage

        // Trigger the app to show the overlay
        AppRouteStore.shared.trigger(.translateScreenshots, preferredTab: .photo)

        // Start processing in background
        Task {
            await store.processScreenshots()
        }

        return .result(
            dialog: IntentDialog("Opening translation view for \(nsImages.count) screenshot(s)...")
        )
        #endif
    }
}

// MARK: - Target Language Enum

enum ShortcutTargetLanguage: String, AppEnum {
    case english
    case chinese

    static var typeDisplayRepresentation: TypeDisplayRepresentation {
        TypeDisplayRepresentation(name: "Target Language")
    }

    static var caseDisplayRepresentations: [ShortcutTargetLanguage: DisplayRepresentation] {
        [
            .english: DisplayRepresentation(title: "English", subtitle: "Translate Chinese to English"),
            .chinese: DisplayRepresentation(title: "中文 (Chinese)", subtitle: "Translate English to Chinese")
        ]
    }

    var toScreenshotTargetLanguage: ScreenshotTargetLanguage {
        switch self {
        case .english: return .english
        case .chinese: return .chinese
        }
    }
}

//
//  CameraScannerView.swift
//  SwiftMandarin
//
//  Camera scanner component using VisionKit DataScannerViewController
//  For real-time text recognition from camera
//

import SwiftUI

#if os(iOS)
import VisionKit

/// SwiftUI wrapper for DataScannerViewController
struct CameraScannerView: UIViewControllerRepresentable {
    @Binding var recognizedText: String
    @Binding var isScanning: Bool
    let onTextRecognized: (String) -> Void
    let onDismiss: () -> Void

    // Check if device supports data scanning
    static var isSupported: Bool {
        DataScannerViewController.isSupported
    }

    static var isAvailable: Bool {
        DataScannerViewController.isAvailable
    }

    func makeUIViewController(context: Context) -> UIViewController {
        // Double-check availability before creating scanner
        guard DataScannerViewController.isSupported && DataScannerViewController.isAvailable else {
            // Return a placeholder controller if scanner isn't available
            let placeholder = UIViewController()
            placeholder.view.backgroundColor = .systemBackground
            return placeholder
        }

        let scanner = DataScannerViewController(
            recognizedDataTypes: [.text()],
            qualityLevel: .accurate,
            recognizesMultipleItems: true,
            isHighFrameRateTrackingEnabled: true,
            isPinchToZoomEnabled: true,
            isGuidanceEnabled: true,
            isHighlightingEnabled: true
        )
        scanner.delegate = context.coordinator
        return scanner
    }

    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {
        // Only control scanning if we have a DataScannerViewController
        guard let scanner = uiViewController as? DataScannerViewController else { return }

        if isScanning {
            if !scanner.isScanning {
                try? scanner.startScanning()
            }
        } else {
            if scanner.isScanning {
                scanner.stopScanning()
            }
        }
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }

    class Coordinator: NSObject, DataScannerViewControllerDelegate {
        let parent: CameraScannerView
        private var lastRecognizedText: String = ""

        init(_ parent: CameraScannerView) {
            self.parent = parent
        }

        func dataScanner(_ dataScanner: DataScannerViewController, didTapOn item: RecognizedItem) {
            switch item {
            case .text(let text):
                let cleanedText = cleanTextForSentences(text.transcript)
                parent.recognizedText = cleanedText
                parent.onTextRecognized(cleanedText)
            default:
                break
            }
        }

        func dataScanner(_ dataScanner: DataScannerViewController, didAdd addedItems: [RecognizedItem], allItems: [RecognizedItem]) {
            // Combine all recognized text and clean it
            let rawText = allItems.compactMap { item -> String? in
                if case .text(let text) = item {
                    return text.transcript
                }
                return nil
            }.joined(separator: " ")

            let cleanedText = cleanTextForSentences(rawText)

            // Only update if text changed significantly
            if cleanedText != lastRecognizedText {
                lastRecognizedText = cleanedText
                parent.recognizedText = cleanedText
            }
        }

        func dataScanner(_ dataScanner: DataScannerViewController, didRemove removedItems: [RecognizedItem], allItems: [RecognizedItem]) {
            // Update text when items are removed
            let rawText = allItems.compactMap { item -> String? in
                if case .text(let text) = item {
                    return text.transcript
                }
                return nil
            }.joined(separator: " ")

            let cleanedText = cleanTextForSentences(rawText)
            lastRecognizedText = cleanedText
            parent.recognizedText = cleanedText
        }

        /// Clean OCR text to properly join sentences split by line breaks
        private func cleanTextForSentences(_ text: String) -> String {
            var result = text

            // Replace multiple whitespace/newlines with single space
            result = result.components(separatedBy: .whitespacesAndNewlines)
                .filter { !$0.isEmpty }
                .joined(separator: " ")

            // Fix hyphenated words split across lines
            result = result.replacingOccurrences(of: "- ", with: "")

            // Ensure proper spacing after punctuation
            result = result.replacingOccurrences(of: "\\.([A-Z])", with: ". $1", options: .regularExpression)
            result = result.replacingOccurrences(of: "\\?([A-Z])", with: "? $1", options: .regularExpression)
            result = result.replacingOccurrences(of: "!([A-Z])", with: "! $1", options: .regularExpression)

            // Clean up multiple spaces
            result = result.replacingOccurrences(of: "  +", with: " ", options: .regularExpression)

            return result.trimmingCharacters(in: .whitespacesAndNewlines)
        }

        func dataScanner(_ dataScanner: DataScannerViewController, becameUnavailableWithError error: DataScannerViewController.ScanningUnavailable) {
            parent.isScanning = false
        }
    }
}

/// Full-screen camera scanner sheet
struct CameraScannerSheet: View {
