        NavigationStack {
            ZStack {
                if isScannerAvailable {
                    CameraScannerView(
                        recognizedText: $recognizedText,
                        isScanning: $isScanning,
                        onTextRecognized: { text in
                            // Optional: Auto-capture on tap
                        },
                        onDismiss: {
                            dismiss()
                        }
                    )
                    .ignoresSafeArea()

                    // Overlay controls
                    VStack {
                        Spacer()

                        // Recognized text preview
                        if !recognizedText.isEmpty {
