                                Text("取消")
                                    .font(.headline)
                                    .foregroundStyle(.white)
                                    .frame(width: 80, height: 44)
                                    .background(.ultraThinMaterial)
                                    .clipShape(Capsule())
                            }

                            Button {
                                capturedText = recognizedText
                                dismiss()
                            } label: {
                                Image(systemName: "checkmark.circle.fill")
                                    .font(.system(size: 64))
                                    .foregroundStyle(.white)
                                    .shadow(radius: 4)
