                        if !CameraScannerView.isSupported {
                            Text("您的设备不支持文字扫描功能")
                        } else {
                            Text("请在设置中允许相机访问权限")
                        }
                    }
                }
            }
            .navigationTitle("扫描文字")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("关闭") {
                        dismiss()
                    }
                }
            }
        }
    }
}

#else
