//
//  ScreenshotTranslationStore.swift
//  SwiftMandarin
//
//  Shared state store for screenshot translation feature
//  Manages the flow from image input through translation to display
//

import Foundation
import SwiftUI
import Translation

#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

/// A translated text block with position information
struct TranslatedTextBlock: Identifiable, Sendable {
    let id = UUID()
    let originalText: String
    let translatedText: String
    /// Bounding box in normalized coordinates (0-1) from Vision
    let boundingBox: CGRect
    /// Confidence score from OCR
    let confidence: Float
}

/// Target language for translation
enum ScreenshotTargetLanguage: String, CaseIterable, Sendable {
    case english = "en"
    case chinese = "zh-Hans"

    var localeLanguage: Locale.Language {
        Locale.Language(identifier: rawValue)
    }

    var displayName: String {
        switch self {
        case .english: return "English"
        case .chinese: return "中文"
        }
    }
}

/// Processing state for the translation workflow
enum ScreenshotProcessingState: Equatable, Sendable {
    case idle
    case stitching
    case recognizingText
    case translating
    case completed
    case error(String)

    var isProcessing: Bool {
        switch self {
        case .stitching, .recognizingText, .translating:
            return true
        default:
            return false
        }
    }

    var statusMessage: String {
        switch self {
        case .idle:
            return "Ready"
        case .stitching:
            return "Stitching screenshots..."
        case .recognizingText:
            return "Recognizing text..."
        case .translating:
            return "Translating..."
        case .completed:
            return "Complete"
        case .error(let message):
            return "Error: \(message)"
        }
    }
}

/// Observable store for screenshot translation state
@Observable
@MainActor
final class ScreenshotTranslationStore {

    static let shared = ScreenshotTranslationStore()

    // MARK: - Input State

    #if canImport(UIKit)
    /// Pending images to process (set by App Intent)
    var pendingImages: [UIImage]?
    #elseif canImport(AppKit)
    /// Pending images to process (set by App Intent)
    var pendingImages: [NSImage]?
    #endif

    /// Target language for translation
    var targetLanguage: ScreenshotTargetLanguage = .english

    // MARK: - Processing State

    /// Current processing state
    var state: ScreenshotProcessingState = .idle

    // MARK: - Output State

    /// Result of image stitching
    var stitchedResult: StitchedImageResult?

    /// OCR results sorted in reading order
    var recognizedBlocks: [RecognizedTextBlock]?

    /// Translated text blocks
    var translatedBlocks: [TranslatedTextBlock]?

    /// Combined translated text in reading order
    var fullTranslatedText: String {
        translatedBlocks?.map { $0.translatedText }.joined(separator: "\n\n") ?? ""
    }

    /// Combined original text in reading order
    var fullOriginalText: String {
        recognizedBlocks?.map { $0.text }.joined(separator: "\n\n") ?? ""
    }

    // MARK: - Computed Properties

    var hasContent: Bool {
        translatedBlocks != nil && !(translatedBlocks?.isEmpty ?? true)
    }

    var hasError: Bool {
        if case .error = state {
            return true
        }
        return false
    }

    var errorMessage: String? {
        if case .error(let message) = state {
            return message
        }
        return nil
    }

    // MARK: - Initialization

    private init() {}

    // MARK: - Public Methods

    /// Process pending screenshots: stitch, OCR, and translate
    func processScreenshots() async {
        guard let images = pendingImages, !images.isEmpty else {
            state = .error("No images to process")
            return
        }

        state = .stitching

        do {
            // Step 1: Stitch images
            let stitched = await ScreenshotStitchingService.shared.stitch(images: images)
            stitchedResult = stitched

            state = .recognizingText

            // Step 2: OCR
            let ocrResult = try await PhotoTextRecognitionService.shared.recognizeText(in: stitched.image)

            // Sort blocks in reading order (top-to-bottom, left-to-right)
            let sortedBlocks = sortInReadingOrder(ocrResult.blocks)
            recognizedBlocks = sortedBlocks

            state = .translating

            // Step 3: Translate
            let translated = try await translateBlocks(sortedBlocks)
            translatedBlocks = translated

            state = .completed

        } catch {
            state = .error(error.localizedDescription)
        }
    }

    /// Clear all state
    func clear() {
        pendingImages = nil
        stitchedResult = nil
        recognizedBlocks = nil
        translatedBlocks = nil
        state = .idle
    }

    /// Reset to process new images
    func reset() {
        stitchedResult = nil
        recognizedBlocks = nil
        translatedBlocks = nil
        state = .idle
    }

    // MARK: - Private Methods

    /// Sort text blocks in reading order
    private func sortInReadingOrder(_ blocks: [RecognizedTextBlock]) -> [RecognizedTextBlock] {
        // Vision coordinates: origin at bottom-left, Y increases upward
        // We want top-to-bottom reading order

        // Group blocks by approximate Y position (rows)
        let rowThreshold: CGFloat = 0.02 // 2% of image height

        var rows: [[RecognizedTextBlock]] = []
        var currentRow: [RecognizedTextBlock] = []
        var currentRowY: CGFloat = -1

        // Sort by Y (descending, so top items come first)
        let sortedByY = blocks.sorted { $0.boundingBox.maxY > $1.boundingBox.maxY }

        for block in sortedByY {
            let blockY = block.boundingBox.maxY

            if currentRowY < 0 {
                // First block
                currentRowY = blockY
                currentRow = [block]
            } else if abs(blockY - currentRowY) <= rowThreshold {
                // Same row
                currentRow.append(block)
            } else {
                // New row
                if !currentRow.isEmpty {
                    // Sort current row by X (left-to-right)
                    rows.append(currentRow.sorted { $0.boundingBox.minX < $1.boundingBox.minX })
                }
                currentRowY = blockY
                currentRow = [block]
            }
        }

        // Don't forget the last row
        if !currentRow.isEmpty {
            rows.append(currentRow.sorted { $0.boundingBox.minX < $1.boundingBox.minX })
        }

        // Flatten rows into final ordered list
        return rows.flatMap { $0 }
    }

    /// Translate text blocks using Translation framework
    private func translateBlocks(_ blocks: [RecognizedTextBlock]) async throws -> [TranslatedTextBlock] {
        guard !blocks.isEmpty else { return [] }

        // Combine all text for batch translation
        // Use a delimiter that won't appear in normal text
        let delimiter = "\n§§§\n"
        let combinedText = blocks.map { $0.text }.joined(separator: delimiter)

        // Translate using the system Translation framework
        let translatedCombined = try await translateText(combinedText)

        // Split back into individual translations
        let translatedTexts = translatedCombined.components(separatedBy: delimiter)

        // Map back to blocks
        var result: [TranslatedTextBlock] = []
        for (index, block) in blocks.enumerated() {
            let translatedText = index < translatedTexts.count ? translatedTexts[index].trimmingCharacters(in: .whitespacesAndNewlines) : block.text

            result.append(TranslatedTextBlock(
                originalText: block.text,
                translatedText: translatedText,
                boundingBox: block.boundingBox,
                confidence: block.confidence
            ))
        }

        return result
    }

    /// Translate text using Apple's Translation framework
    private func translateText(_ text: String) async throws -> String {
        // Use the same translation approach as elsewhere in the app
        // This leverages TranslationSession for on-device translation

        let sourceLanguage: Locale.Language
        let targetLang = targetLanguage.localeLanguage

        // Detect source language - if targeting English, source is likely Chinese and vice versa
        if targetLanguage == .english {
            sourceLanguage = Locale.Language(identifier: "zh-Hans")
        } else {
            sourceLanguage = Locale.Language(identifier: "en")
        }

        // Create translation session using installed languages
        let session = try await TranslationSession(
            installedSource: sourceLanguage,
            target: targetLang
        )

        let response = try await session.translate(text)
        return response.targetText
    }
}

//
//  TranslateTextIntent.swift
//  SwiftMandarin

import Foundation
import AppIntents

struct TranslateTextIntent: AppIntent {
    static var title: LocalizedStringResource = "Translate Text"
    static var description = IntentDescription("Translate text between English and Chinese. Optionally save Chinese phrases (2+ characters) to vocabulary with auto-detected part of speech.")

    @Parameter(title: "Text", inputOptions: .init(capitalizationType: .sentences))
    var text: String

    @Parameter(title: "Direction", default: .auto)
    var direction: ShortcutTranslationDirection

    @Parameter(title: "Use Apple Intelligence", default: false)
    var useAI: Bool

    @Parameter(title: "Save to Vocabulary", default: false)
    var saveToVocabulary: Bool

    static var parameterSummary: some ParameterSummary {
        Summary("Translate \(\.$text) with \(\.$direction)") {
            \.$useAI
            \.$saveToVocabulary
        }
    }

    @MainActor
    func perform() async throws -> some IntentResult & ReturnsValue<String> {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw TranslationIntentError.emptyText
        }

        let resolvedDirection = ShortcutHelpers.resolveDirection(for: trimmed, preferred: direction)

        let result = try await ShortcutHelpers.translate(trimmed, direction: resolvedDirection, useAI: useAI)

        // Save to translation history
        TranslationHistoryStore.shared.add(
            source: trimmed,
            target: result.translation,
            direction: resolvedDirection
        )

        // Save Chinese phrases to vocabulary if enabled
        if saveToVocabulary {
            let chinese = resolvedDirection == .englishToChinese ? result.translation : trimmed
            let english = resolvedDirection == .englishToChinese ? trimmed : result.translation

            ShortcutHelpers.saveChinesePhrasesToVocabulary(
                chineseText: chinese,
                englishTranslation: english
            )
        }

        let dialog = useAI && !result.usedAI
            ? IntentDialog("Apple Intelligence wasn't available, so SwiftMandarin used standard translation.")
            : IntentDialog("Translation complete.")

        return .result(value: result.translation, dialog: dialog)
    }
}

enum TranslationIntentError: LocalizedError {
    case emptyText
    case translationFailed(String)
    case noImages
    case invalidImages

    var errorDescription: String? {
        switch self {
        case .emptyText:
            return "Please provide text to translate."
        case .translationFailed(let message):
            return message
        case .noImages:
            return "No images provided."
        case .invalidImages:
            return "Could not load the provided images."
        }
    }
}

//
//  ScreenshotStitchingService.swift
//  SwiftMandarin
//
//  Service for stitching multiple screenshots into a single vertical image
//  with automatic overlap detection and removal
//

import Foundation
import CoreGraphics

#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

/// Result of stitching multiple screenshots
struct StitchedImageResult: Sendable {
    #if canImport(UIKit)
    let image: UIImage
    #elseif canImport(AppKit)
    let image: NSImage
    #endif

    /// Y-positions where original images were joined (in final image coordinates)
    let pageBreaks: [CGFloat]

    /// Heights of each original image before stitching
    let originalHeights: [CGFloat]

    /// Detected overlap heights between consecutive images
    let overlapHeights: [Int]

    /// Total height of the stitched image
    var totalHeight: CGFloat {
        #if canImport(UIKit)
        return image.size.height
        #elseif canImport(AppKit)
        return image.size.height
        #endif
    }
}

/// Service for stitching multiple screenshots into one continuous image
@MainActor
final class ScreenshotStitchingService {

    static let shared = ScreenshotStitchingService()

    /// Configuration for overlap detection
    struct Configuration {
        /// Maximum overlap to search for (in pixels)
        var maxOverlapPixels: Int = 300

        /// Minimum overlap to consider valid
        var minOverlapPixels: Int = 20

        /// Similarity threshold for matching (0.0-1.0)
        var similarityThreshold: Float = 0.90

        /// Width of the comparison strip (center portion of image)
        var comparisonStripWidthRatio: CGFloat = 0.6

        /// Row sampling interval for faster comparison
        var rowSampleInterval: Int = 2
    }

    var configuration = Configuration()

    private init() {}

    // MARK: - Public Methods

    #if canImport(UIKit)
    /// Stitch multiple UIImages into one vertical image, removing overlaps
    func stitch(images: [UIImage]) async -> StitchedImageResult {
        guard !images.isEmpty else {
            // Return empty result
            return StitchedImageResult(
                image: UIImage(),
                pageBreaks: [],
                originalHeights: [],
                overlapHeights: []
            )
        }

        guard images.count > 1 else {
            // Single image, no stitching needed
            return StitchedImageResult(
                image: images[0],
                pageBreaks: [],
                originalHeights: [images[0].size.height],
                overlapHeights: []
            )
        }

        // Calculate overlaps between consecutive images
        var overlapHeights: [Int] = []
        for i in 0..<(images.count - 1) {
            let overlap = await findOverlapHeight(
                topImage: images[i],
                bottomImage: images[i + 1]
            )
            overlapHeights.append(overlap)
        }

        // Calculate total height and page breaks
        var totalHeight: CGFloat = 0
        var pageBreaks: [CGFloat] = []
        let originalHeights = images.map { $0.size.height }

        for (index, image) in images.enumerated() {
            if index == 0 {
                totalHeight += image.size.height
            } else {
                let overlap = CGFloat(overlapHeights[index - 1])
                pageBreaks.append(totalHeight)
                totalHeight += image.size.height - overlap
            }
        }

        // Use the width of the first image
        let width = images[0].size.width

        // Create the stitched image
        let renderer = UIGraphicsImageRenderer(size: CGSize(width: width, height: totalHeight))

        let stitchedImage = renderer.image { context in
            var yOffset: CGFloat = 0

            for (index, image) in images.enumerated() {
                if index == 0 {
                    // Draw first image fully
                    image.draw(at: CGPoint(x: 0, y: yOffset))
                    yOffset += image.size.height
                } else {
                    // Skip the overlapping portion at the top
                    let overlap = CGFloat(overlapHeights[index - 1])
                    let cropRect = CGRect(
                        x: 0,
                        y: overlap,
                        width: image.size.width,
                        height: image.size.height - overlap
                    )

                    if let cgImage = image.cgImage,
                       let croppedCGImage = cgImage.cropping(to: cropRect) {
                        let croppedImage = UIImage(cgImage: croppedCGImage, scale: image.scale, orientation: image.imageOrientation)
                        croppedImage.draw(at: CGPoint(x: 0, y: yOffset))
                        yOffset += croppedImage.size.height
                    }
                }
            }
        }

        return StitchedImageResult(
            image: stitchedImage,
            pageBreaks: pageBreaks,
            originalHeights: originalHeights,
            overlapHeights: overlapHeights
        )
    }
    #endif

    #if canImport(AppKit)
    /// Stitch multiple NSImages into one vertical image, removing overlaps
    func stitch(images: [NSImage]) async -> StitchedImageResult {
        guard !images.isEmpty else {
            return StitchedImageResult(
                image: NSImage(),
                pageBreaks: [],
                originalHeights: [],
                overlapHeights: []
            )
        }

        guard images.count > 1 else {
            return StitchedImageResult(
                image: images[0],
                pageBreaks: [],
                originalHeights: [images[0].size.height],
                overlapHeights: []
            )
        }

        // Calculate overlaps between consecutive images
        var overlapHeights: [Int] = []
        for i in 0..<(images.count - 1) {
            let overlap = await findOverlapHeight(
                topImage: images[i],
                bottomImage: images[i + 1]
            )
            overlapHeights.append(overlap)
        }

        // Calculate total height and page breaks
        var totalHeight: CGFloat = 0
        var pageBreaks: [CGFloat] = []
        let originalHeights = images.map { $0.size.height }

        for (index, image) in images.enumerated() {
            if index == 0 {
                totalHeight += image.size.height
            } else {
                let overlap = CGFloat(overlapHeights[index - 1])
                pageBreaks.append(totalHeight)
                totalHeight += image.size.height - overlap
            }
        }

        let width = images[0].size.width

        // Create the stitched image
        let stitchedImage = NSImage(size: NSSize(width: width, height: totalHeight))
        stitchedImage.lockFocus()

        var yOffset: CGFloat = totalHeight // Start from top (NSImage coordinates are flipped)

        for (index, image) in images.enumerated() {
            if index == 0 {
                yOffset -= image.size.height
                image.draw(at: NSPoint(x: 0, y: yOffset), from: .zero, operation: .copy, fraction: 1.0)
            } else {
                let overlap = CGFloat(overlapHeights[index - 1])
                let drawHeight = image.size.height - overlap
                yOffset -= drawHeight

                let sourceRect = NSRect(x: 0, y: 0, width: image.size.width, height: drawHeight)
                let destRect = NSRect(x: 0, y: yOffset, width: image.size.width, height: drawHeight)
                image.draw(in: destRect, from: sourceRect, operation: .copy, fraction: 1.0)
            }
        }

        stitchedImage.unlockFocus()

        return StitchedImageResult(
            image: stitchedImage,
            pageBreaks: pageBreaks,
            originalHeights: originalHeights,
            overlapHeights: overlapHeights
        )
    }
    #endif

    // MARK: - Private Methods

    #if canImport(UIKit)
    /// Find the overlap height between two vertically adjacent images
    private func findOverlapHeight(topImage: UIImage, bottomImage: UIImage) async -> Int {
        guard let topCG = topImage.cgImage,
              let bottomCG = bottomImage.cgImage else {
            return 0
        }

        return await findOverlapHeight(topCG: topCG, bottomCG: bottomCG)
    }
    #endif

    #if canImport(AppKit)
    /// Find the overlap height between two vertically adjacent images
    private func findOverlapHeight(topImage: NSImage, bottomImage: NSImage) async -> Int {
        guard let topCG = topImage.cgImage(forProposedRect: nil, context: nil, hints: nil),
              let bottomCG = bottomImage.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
            return 0
        }

        return await findOverlapHeight(topCG: topCG, bottomCG: bottomCG)
    }
    #endif

    /// Core overlap detection algorithm using pixel comparison
    private func findOverlapHeight(topCG: CGImage, bottomCG: CGImage) async -> Int {
        let topHeight = topCG.height
        let bottomHeight = bottomCG.height
        let width = min(topCG.width, bottomCG.width)

        // Calculate the center strip to compare
        let stripStart = Int(CGFloat(width) * (1.0 - configuration.comparisonStripWidthRatio) / 2.0)
        let stripEnd = Int(CGFloat(width) * (1.0 + configuration.comparisonStripWidthRatio) / 2.0)
        let stripWidth = stripEnd - stripStart

        // Get pixel data for both images
        guard let topData = getPixelData(from: topCG),
              let bottomData = getPixelData(from: bottomCG) else {
            return 0
        }

        let bytesPerPixel = 4
        let topBytesPerRow = topCG.bytesPerRow
        let bottomBytesPerRow = bottomCG.bytesPerRow

        var bestOverlap = 0
        var bestSimilarity: Float = 0

        // Search for the best overlap
        let maxOverlap = min(configuration.maxOverlapPixels, min(topHeight, bottomHeight) / 2)

        for overlap in stride(from: configuration.minOverlapPixels, to: maxOverlap, by: configuration.rowSampleInterval) {
            var matchingPixels = 0
            var totalPixels = 0

            // Compare rows
            for row in stride(from: 0, to: overlap, by: configuration.rowSampleInterval) {
                let topRow = topHeight - overlap + row
                let bottomRow = row

                for col in stride(from: stripStart, to: stripEnd, by: 2) {
                    let topOffset = topRow * topBytesPerRow + col * bytesPerPixel
                    let bottomOffset = bottomRow * bottomBytesPerRow + col * bytesPerPixel

                    guard topOffset + 2 < topData.count,
                          bottomOffset + 2 < bottomData.count else {
                        continue
                    }

                    // Compare RGB values (ignore alpha)
                    let rDiff = abs(Int(topData[topOffset]) - Int(bottomData[bottomOffset]))
                    let gDiff = abs(Int(topData[topOffset + 1]) - Int(bottomData[bottomOffset + 1]))
                    let bDiff = abs(Int(topData[topOffset + 2]) - Int(bottomData[bottomOffset + 2]))

                    // Consider pixels matching if color difference is small
                    if rDiff < 30 && gDiff < 30 && bDiff < 30 {
                        matchingPixels += 1
                    }
                    totalPixels += 1
                }
            }

            guard totalPixels > 0 else { continue }

            let similarity = Float(matchingPixels) / Float(totalPixels)

            if similarity > bestSimilarity && similarity >= configuration.similarityThreshold {
                bestSimilarity = similarity
                bestOverlap = overlap
            }
        }

        return bestOverlap
    }

    /// Extract raw pixel data from a CGImage
    private func getPixelData(from image: CGImage) -> [UInt8]? {
        let width = image.width
        let height = image.height
        let bytesPerPixel = 4
        let bytesPerRow = bytesPerPixel * width
        let bitsPerComponent = 8

        var pixelData = [UInt8](repeating: 0, count: height * bytesPerRow)

        guard let colorSpace = CGColorSpace(name: CGColorSpace.sRGB),
              let context = CGContext(
                  data: &pixelData,
                  width: width,
                  height: height,
                  bitsPerComponent: bitsPerComponent,
                  bytesPerRow: bytesPerRow,
                  space: colorSpace,
                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
              ) else {
            return nil
        }

        context.draw(image, in: CGRect(x: 0, y: 0, width: width, height: height))

        return pixelData
    }
}

//
//  TranslationDirection.swift
//  SwiftMandarin
//
//  Translation direction enum for English ↔ Chinese
//

import Foundation
import SwiftUI

enum TranslationDirection: String, CaseIterable, Identifiable, Codable {
    case englishToChinese
    case chineseToEnglish

    var id: String { rawValue }

    var label: String {
        switch self {
        case .englishToChinese: return "EN → 中"
        case .chineseToEnglish: return "中 → EN"
        }
    }

    var sourceLabel: String {
        switch self {
        case .englishToChinese: return "English"
        case .chineseToEnglish: return "中文"
        }
    }

    var targetLabel: String {
        switch self {
        case .englishToChinese: return "中文"
        case .chineseToEnglish: return "English"
        }
    }

    var placeholder: String {
        switch self {
        case .englishToChinese: return "Enter English text..."
        case .chineseToEnglish: return "输入中文..."
        }
    }

    var sourceLanguage: Locale.Language {
        switch self {
        case .englishToChinese: return Locale.Language(identifier: "en")
        case .chineseToEnglish: return Locale.Language(identifier: "zh-Hans")
        }
    }

    var targetLanguage: Locale.Language {
        switch self {
        case .englishToChinese: return Locale.Language(identifier: "zh-Hans")
        case .chineseToEnglish: return Locale.Language(identifier: "en")
        }
    }

    var sourceSpeechCode: String {
        switch self {
        case .englishToChinese: return "en-US"
        case .chineseToEnglish: return "zh-CN"
        }
    }

    var targetSpeechCode: String {
        switch self {
        case .englishToChinese: return "zh-CN"
        case .chineseToEnglish: return "en-US"
        }
    }

    var opposite: TranslationDirection {
        self == .englishToChinese ? .chineseToEnglish : .englishToChinese
    }

    var sourceLanguageName: String {
        switch self {
        case .englishToChinese: return "English"
        case .chineseToEnglish: return "Chinese"
        }
    }

    var targetLanguageName: String {
        switch self {
        case .englishToChinese: return "Chinese"
        case .chineseToEnglish: return "English"
        }
    }

    func toggled() -> TranslationDirection {
        opposite
    }
}

