import Foundation
import AppIntents

struct GetLearningStatsIntent: AppIntent {
    static var title: LocalizedStringResource = "Get Learning Stats"
    static var description = IntentDescription("Get SwiftMandarin learning stats for a selected time range.")

    @Parameter(title: "Range", default: .last7Days)
    var range: ShortcutStatsRange

    static var parameterSummary: some ParameterSummary {
        Summary("Get learning stats for \(\.$range)")
    }

    func perform() async throws -> some IntentResult & ReturnsValue<String> {
        let summaryText = await MainActor.run {
            LearningStatsSummary(range: range).formatted
        }
        return .result(value: summaryText)
    }
}

private struct LearningStatsSummary {
    let wordsLearned: Int
    let reviewsCompleted: Int
    let translationsMade: Int
    let streak: Int

    init(range: ShortcutStatsRange) {
        let activityStore = LearningActivityStore.shared
        switch range {
        case .today:
            let today = activityStore.activity(for: Date())
            wordsLearned = today.wordsLearned
            reviewsCompleted = today.reviewsCompleted
            translationsMade = today.translationsMade
        case .last7Days:
            let activities = activityStore.activitiesForLastDays(7)
            wordsLearned = activities.reduce(0) { $0 + $1.wordsLearned }
            reviewsCompleted = activities.reduce(0) { $0 + $1.reviewsCompleted }
            translationsMade = activities.reduce(0) { $0 + $1.translationsMade }
        case .last30Days:
            let activities = activityStore.activitiesForLastDays(30)
            wordsLearned = activities.reduce(0) { $0 + $1.wordsLearned }
            reviewsCompleted = activities.reduce(0) { $0 + $1.reviewsCompleted }
            translationsMade = activities.reduce(0) { $0 + $1.translationsMade }
        case .allTime:
            wordsLearned = activityStore.totalWordsLearned
            reviewsCompleted = activityStore.totalReviewsCompleted
            translationsMade = activityStore.totalTranslationsMade
        }

        streak = activityStore.currentStreak
    }

    var formatted: String {
        "Words learned: \(wordsLearned)\nReviews: \(reviewsCompleted)\nTranslations: \(translationsMade)\nCurrent streak: \(streak)"
    }
}

//
//  LiveSpeechTranslationView.swift
//  SwiftMandarin
//
//  Live speech-to-text translation view
//  Captures speech, transcribes it, and translates in real-time
//

import SwiftUI
import Translation

/// Live speech translation view that appears as a sheet/popup
/// Captures speech, transcribes it, and translates to the target language
struct LiveSpeechTranslationView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(SavedTermsStore.self) private var savedTermsStore

    /// The translation direction determines target language
    let translationDirection: TranslationDirection

    /// Callback when user wants to use the transcribed text
    let onUseTranscript: (String) -> Void

    /// Callback when user wants to use the translated text
    let onUseTranslation: (String) -> Void

    // MARK: - State

    @State private var speechService = SpeechRecognitionService.shared
    @State private var isRecording = false
    @State private var transcript = ""
    @State private var translatedText = ""
    @State private var isTranslating = false
    @State private var translationError: String?
    @State private var translationConfiguration: TranslationSession.Configuration?
    @State private var selectedLanguage: SpeechRecognitionLanguage = .english
    @State private var showPermissionAlert = false
    @State private var permissionAlertMessage = ""
    @State private var pulseAnimation = false
    @State private var lastDetectedDirection: TranslationDirection?
    @State private var translationTask: Task<Void, Never>?
    @State private var lastTranslationText: String = ""

    // For word analysis
    @State private var selectedSegment: RubySegment?

    /// The speech language based on translation direction
    private var defaultSpeechLanguage: SpeechRecognitionLanguage {
        switch translationDirection {
        case .englishToChinese:
            return .english
        case .chineseToEnglish:
            return .chinese
        }
    }

    /// Target language for translation
    private var targetLanguage: String {
        translationDirection.targetLanguageName
    }

    /// Whether transcribed text contains Chinese characters
    private var transcriptContainsChinese: Bool {
        transcript.contains { $0.isChineseCharacter }
    }

    /// Platform-aware background gradient
    private var backgroundGradient: some View {
        #if os(iOS)
        LinearGradient(
            colors: [
                Color(uiColor: .systemBackground),
                speechService.isRecording ? Color.red.opacity(0.05) : Color.accentColor.opacity(0.05)
            ],
            startPoint: .top,
            endPoint: .bottom
        )
        #else
        LinearGradient(
            colors: [
                Color(nsColor: .windowBackgroundColor),
                speechService.isRecording ? Color.red.opacity(0.05) : Color.accentColor.opacity(0.05)
            ],
            startPoint: .top,
            endPoint: .bottom
        )
        #endif
    }

    var body: some View {
        NavigationStack {
            ZStack {
                // Background gradient
                backgroundGradient
                    .ignoresSafeArea()

                VStack(spacing: 0) {
                    // Language selector header
                    languageSelector
                        .padding(.horizontal)
                        .padding(.top, 8)
                        .padding(.bottom, 12)

                    // Main content
                    ScrollView {
                        VStack(spacing: 24) {
                            // Recording section - always visible
                            recordingSection
                                .padding(.top, 8)

                            // Transcript section
                            if !transcript.isEmpty || speechService.isRecording {
                                transcriptSection
                                    .transition(.opacity.combined(with: .move(edge: .top)))
                            }

                            // Translation section
                            if !translatedText.isEmpty || isTranslating {
                                translationSection
                                    .transition(.opacity.combined(with: .move(edge: .top)))
                            }

                            // Empty state when not recording and no content
                            if transcript.isEmpty && !speechService.isRecording {
