    private func processText(_ text: String) async {
        guard !text.isEmpty else { return }

        await MainActor.run {
            isProcessing = true
            errorMessage = nil
            // Clear previous results
            analyzedSentences = []
            cleanedChineseText = ""
            chineseTranslation = ""
