    private func loadImages(
        _ items: [PhotosPickerItem],
        into keyPath: ReferenceWritableKeyPath<WorkbookGradingView, [Data]>,
        loading loadingKeyPath: ReferenceWritableKeyPath<WorkbookGradingView, Bool>
    ) async {
        // Note: WorkbookGradingView is a struct; use explicit state setters below.
        // (This helper is intentionally simple and assigns via the wrappers.)
        await MainActor.run { setLoading(loadingKeyPath, true) }
        var datas: [Data] = []
        for item in items {
            if let data = try? await item.loadTransferable(type: Data.self) {
                datas.append(downscaledJPEG(data))
            }
        }
        let finalDatas = datas
        await MainActor.run {
            assign(keyPath, finalDatas)
            setLoading(loadingKeyPath, false)
        }
    }

    private func grade() async {
        await MainActor.run {
            isGrading = true
            errorMessage = nil
            result = nil
            savedQuestionIDs = []
