        // Note: WorkbookGradingView is a struct; use explicit state setters below.
        // (This helper is intentionally simple and assigns via the wrappers.)
        await MainActor.run { setLoading(loadingKeyPath, true) }
        var datas: [Data] = []
        for item in items {
            if let data = try? await item.loadTransferable(type: Data.self) {
                datas.append(downscaledJPEG(data))
