    let onSaveVocab: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .top) {
                Image(systemName: question.isCorrect ? "checkmark.circle.fill" : "xmark.circle.fill")
