    /// Results section for Chinese text (Chinese → English)
    private var chineseResultsSection: some View {
        VStack(spacing: 16) {
            // Summary
            HStack {
                VStack(alignment: .leading) {
                    HStack {
                        Text("分析结果")
                            .font(.headline)
